@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"STAY_WORKER_ENABLED=false","RAIL_TICKET_WORKER_ENABLED=false","travbook.payments.refund-worker-enabled=false"})
@org.springframework.test.annotation.DirtiesContext(classMode=org.springframework.test.annotation.DirtiesContext.ClassMode.AFTER_CLASS)
@Import(RailTicketIntegrationTest.TimeConfig.class)
@Testcontainers
class RailTicketIntegrationTest {
 static final TestIssuer issuer=new TestIssuer();@Container static PostgreSQLContainer postgres=new PostgreSQLContainer("postgres:17.6-alpine");
 @DynamicPropertySource static void database(DynamicPropertyRegistry r){r.add("spring.datasource.url",postgres::getJdbcUrl);r.add("spring.datasource.username",postgres::getUsername);r.add("spring.datasource.password",postgres::getPassword);r.add("travbook.oidc-issuer",issuer::url);r.add("travbook.local-identity",()->true);}
 @TestConfiguration static class TimeConfig{@Bean @Primary MutableClock testClock(){return new MutableClock();}}
 static class MutableClock extends Clock{volatile Instant now=Instant.now();public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId zone){return Clock.fixed(now,zone);}public Instant instant(){return now;}}
 @Autowired MutableClock clock;@Autowired RailTickets tickets;@Autowired DiscoverTrains trains;@Autowired Customers customers;@Autowired ProcessRailTickets worker;@Autowired RailTicketStore store;@Autowired RailTicketSelection selections;@Autowired RailTicketEffects effects;@Autowired RailReservations supplier;@Autowired PaymentRefunds refunds;@Autowired com.travbook.payments.application.port.in.PaymentOperations payments;@Autowired JdbcClient jdbc;@Autowired ObjectMapper json;@LocalServerPort int port;
 @TempDir Path temp;static final AtomicInteger day=new AtomicInteger(5);CustomerIdentity identity;UUID owner;String token;final HttpClient http=HttpClient.newHttpClient();
 @BeforeEach void reset()throws Exception{clock.now=Instant.now();identity=new CustomerIdentity(issuer.url(),"rail-ticket-"+UUID.randomUUID());owner=customers.resolve(identity).id();token=issuer.token(identity.subject(),"bookings:read bookings:write");}
 @AfterAll static void closeIssuer(){issuer.close();}
 String key(){return UUID.randomUUID().toString();}UUID correlation(){return UUID.randomUUID();}
 RailTickets.QuoteDetails quote(){return quote(Rail.TravelClass.SL,1);}
 RailTickets.QuoteDetails quote(Rail.TravelClass type,int count){var date=LocalDate.now(ZoneId.of("Asia/Kolkata")).plusDays(day.incrementAndGet());return quoteAt(date,type,count);}
 RailTickets.QuoteDetails quoteAt(LocalDate date,Rail.TravelClass type,int count){var p=trains.search(new Rail.Criteria("NDLS","MMCT",date,Rail.Quota.GENERAL));var j=p.items().stream().filter(v->v.departure().getHour()==8).findFirst().orElseThrow();return tickets.quote(identity,j.id(),type,Rail.Quota.GENERAL,"NDLS",people(count),key(),correlation());}
 List<Passenger> people(int count){return java.util.stream.IntStream.range(0,count).mapToObj(i->new Passenger("Alex "+(char)('A'+i),"Example",LocalDate.parse("1990-01-01"),Berth.LOWER)).toList();}
 Booking book(RailTickets.QuoteDetails q,Scenario scenario){tickets.accept(identity,q.quote().id(),1,true,key(),correlation());return tickets.book(identity,q.quote().id(),1,scenario,true,key(),correlation());}
 void due(UUID id){jdbc.sql("update rail_ticket_work set next_at=clock_timestamp()-interval '1 second',lease_until=null where booking_id=:id and state in('READY','RUNNING')").param("id",id).update();}
 Booking finish(UUID id){for(int i=0;i<30;i++){var b=tickets.get(identity,id);if(b.terminal())return b;due(id);worker.tick();refunds.settleNext();}throw new AssertionError("Workflow did not finish");}
 int count(String table,String column,UUID id){return jdbc.sql("select count(*) from "+table+" where "+column+"=:id").param("id",id).query(Integer.class).single();}
 HttpResponse<String> call(String method,String path,String auth,String key,Object body)throws Exception{var r=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+path)).timeout(Duration.ofSeconds(10));if(auth!=null)r.header("Authorization","Bearer "+auth);if(key!=null)r.header("Idempotency-Key",key);if(method.equals("POST"))r.header("Content-Type","application/json").POST(body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(json.writeValueAsString(body)));else r.GET();return http.send(r.build(),HttpResponse.BodyHandlers.ofString());}
 @Test void concurrentDuplicateBookingCommandsYieldOneWorkflowAndOneCapture()throws Exception{var q=quote();tickets.accept(identity,q.quote().id(),1,true,key(),correlation());String key=key();List<Booking> results;try(var pool=Executors.newFixedThreadPool(2)){var calls=pool.invokeAll(List.<Callable<Booking>>of(()->tickets.book(identity,q.quote().id(),1,Scenario.SUCCESS,true,key,correlation()),()->tickets.book(identity,q.quote().id(),1,Scenario.SUCCESS,true,key,correlation())));results=List.of(calls.get(0).get(),calls.get(1).get());}assertThat(results.get(0).id()).isEqualTo(results.get(1).id());var b=finish(results.getFirst().id());assertThat(b.status()).isEqualTo(Status.ISSUED);assertThat(count("rail_provider_operation","reservation_id",b.id())).isEqualTo(1);assertThat(count("payment_operation","payment_id",b.id())).isEqualTo(2);assertThat(count("payment_journal","payment_id",b.id())).isEqualTo(2);
  assertThatThrownBy(()->tickets.book(identity,q.quote().id(),1,Scenario.AUTH_DECLINED,true,key,correlation())).isInstanceOf(DomainFailure.class).hasMessageContaining("different rail inputs");assertThat(tickets.getQuote(identity,q.quote().id()).bookingId()).isEqualTo(b.id());assertThat(jdbc.sql("select sum(case when direction='DEBIT' then amount else -amount end) from payment_journal where payment_id=:id").param("id",b.id()).query(java.math.BigDecimal.class).single()).isEqualByComparingTo("0");
 }
 @Test void supplierAndPaymentFailuresAreCompensatedWithoutFalseConfirmation(){for(var scenario:List.of(Scenario.AUTH_DECLINED,Scenario.RESERVATION_REJECTED,Scenario.CAPTURE_DECLINED)){var b=finish(book(quote(),scenario).id());assertThat(b.status()).isEqualTo(Status.FAILED);assertThat(b.payment()).isEqualTo(scenario==Scenario.AUTH_DECLINED?Payment.DECLINED:Payment.VOIDED);assertThat(count("payment_journal","payment_id",b.id())).isZero();assertThat(jdbc.sql("select count(*) from rail_provider_reservation where id=:id and active").param("id",b.id()).query(Integer.class).single()).isZero();}}
 @Test void lostReservationAndCaptureResponsesRecoverOnce(){for(var scenario:List.of(Scenario.RESERVATION_RESPONSE_LOST,Scenario.CAPTURE_RESPONSE_LOST)){var b=finish(book(quote(),scenario).id());assertThat(b.status()).isEqualTo(Status.ISSUED);assertThat(count("rail_provider_operation","reservation_id",b.id())).isEqualTo(1);assertThat(count("payment_journal","payment_id",b.id())).isEqualTo(2);}}
 @Test void staleLeaseCannotPublishAndUnknownLookupStopsInReview(){var b=book(quote(),Scenario.SUCCESS);var claim=store.claim().orElseThrow();due(b.id());assertThat(store.complete(claim,claim.booking().validated(clock.instant()))).isFalse();var bad=new RailTicketEffects(){public Optional<Result> lookup(Booking booking,Step step){throw new IllegalStateException("Unknown provider outcome");}public Result execute(Booking booking,Step step){throw new AssertionError("Must never repeat unknown effect");}};var w=new RailTicketWorker(store,selections,bad,clock);for(int i=0;i<8;i++){due(b.id());w.tick();}assertThat(tickets.get(identity,b.id()).status()).isEqualTo(Status.REVIEW);assertThat(count("payment_operation","payment_id",b.id())).isZero();}
 @Test void actualJvmLossAfterProviderCommitRecoversWithoutDuplicateEffects()throws Exception{for(String phase:List.of("RESERVE","CAPTURE","CANCEL","REFUND")){var b=book(quote(),Scenario.SUCCESS);boolean aftercare=phase.equals("CANCEL")||phase.equals("REFUND");if(aftercare){finish(b.id());var cq=tickets.cancellationQuote(identity,b.id(),key(),correlation());tickets.cancel(identity,b.id(),cq.id(),true,false,false,key(),correlation());if(phase.equals("REFUND"))worker.tick();}else{worker.tick();worker.tick();if(phase.equals("CAPTURE"))worker.tick();}assertThat(child(phase)).isEqualTo(29);due(b.id());assertThat(child("RESUME")).isZero();var done=finish(b.id());assertThat(done.status()).isEqualTo(aftercare?Status.CANCELLED:Status.ISSUED);assertThat(count("rail_provider_operation","reservation_id",b.id())).isEqualTo(aftercare?2:1);assertThat(count("payment_journal","payment_id",b.id())).isEqualTo(2);if(aftercare){assertThat(done.refund()).isEqualTo(Refund.SUCCEEDED);assertThat(count("payment_refund_journal","operation_id",b.operation(Step.REFUND))).isEqualTo(2);}}}
 @Test void outboxFailureRollsBackBookingAndWorkflowCompletion(){var b=book(quote(),Scenario.SUCCESS);var claim=store.claim().orElseThrow();jdbc.sql("create function fail_rail_ticket_event_test() returns trigger language plpgsql as $$ begin raise exception 'Injected hotel event failure'; end $$").update();jdbc.sql("create trigger fail_rail_ticket_event_test before insert on rail_ticket_outbox for each row execute function fail_rail_ticket_event_test()").update();try{assertThatThrownBy(()->store.complete(claim,claim.booking().validated(clock.instant()))).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(tickets.get(identity,b.id()).version()).isEqualTo(1);assertThat(count("rail_ticket_outbox","aggregate_id",b.id())).isEqualTo(1);}finally{jdbc.sql("drop trigger fail_rail_ticket_event_test on rail_ticket_outbox").update();jdbc.sql("drop function fail_rail_ticket_event_test()").update();}due(b.id());assertThat(finish(b.id()).status()).isEqualTo(Status.ISSUED);}
 @Test void inconsistentProviderReceiptCannotBecomeVerifiedSuccess(){var b=book(quote(),Scenario.SUCCESS);for(boolean accepted:List.of(true,false)){var wrong=new com.travbook.payments.application.port.in.PaymentOperations(){public Optional<Receipt> lookup(UUID op){return Optional.of(new Receipt(op,b.id(),com.travbook.payments.domain.model.Payment.State.CAPTURED,accepted,"MOCK-PAY-"+b.id(),b.quote().selection().total().amount(),"INR","MOCK"));}public Receipt execute(Command c){throw new AssertionError("No effective call expected");}};var adapter=new com.travbook.railtickets.adapter.out.commerce.RailTicketEffectAdapter(wrong,refunds,supplier);assertThatThrownBy(()->adapter.lookup(b,Step.AUTHORIZE)).isInstanceOf(IllegalStateException.class).hasMessageContaining("state or operation");}var changed=new RailReservations(){public Optional<Receipt> lookup(UUID op){return Optional.of(new Receipt(op,b.id(),Reservation.CONFIRMED,true,"MOCK-PNR-"+b.id(),"MOCK"));}public Receipt reserve(UUID op,UUID id,Quote quote,boolean reject){throw new AssertionError("No reserve expected");}public Receipt cancel(UUID op,UUID id){throw new AssertionError("No cancellation expected");}};var changedAdapter=new com.travbook.railtickets.adapter.out.commerce.RailTicketEffectAdapter(payments,refunds,changed);assertThatThrownBy(()->changedAdapter.lookup(b,Step.RESERVE)).isInstanceOf(IllegalStateException.class).hasMessageContaining("binding mismatch");assertThat(tickets.get(identity,b.id()).payment()).isEqualTo(Payment.NOT_STARTED);assertThat(finish(b.id()).status()).isEqualTo(Status.ISSUED);}
 @Test void eligibilityOwnershipConsentAndImmutableExpiry()throws Exception{
  var q=quote();var j=q.quote().selection().journey();assertThat(call("GET","/api/v1/rail-ticket-quotes/"+q.quote().id(),null,null,null).statusCode()).isEqualTo(401);String bob=issuer.token("bob-"+key(),"bookings:read bookings:write");assertThat(call("GET","/api/v1/rail-ticket-quotes/"+q.quote().id(),bob,null,null).statusCode()).isEqualTo(404);
  assertThat(call("POST","/api/v1/rail-ticket-quotes/"+q.quote().id()+"/acceptance",token,key(),Map.of("version",1,"consent",false)).statusCode()).isEqualTo(400);
  assertThatThrownBy(()->tickets.book(identity,q.quote().id(),1,Scenario.SUCCESS,true,key(),correlation())).isInstanceOf(DomainFailure.class).hasMessageContaining("Accept");
  assertThatThrownBy(()->tickets.quote(identity,j.id(),Rail.TravelClass.SL,Rail.Quota.GENERAL,"MMCT",people(1),key(),correlation())).isInstanceOf(DomainFailure.class).hasMessageContaining("origin");
  for(int age:List.of(4,10,121)){var child=List.of(new Passenger("Child","Example",j.departure().toLocalDate().minusYears(age),Berth.NONE));assertThatThrownBy(()->tickets.quote(identity,j.id(),Rail.TravelClass.SL,Rail.Quota.GENERAL,"NDLS",child,key(),correlation())).isInstanceOf(DomainFailure.class);}
  assertThatThrownBy(()->tickets.quote(identity,j.id(),Rail.TravelClass.SL,Rail.Quota.TATKAL,"NDLS",people(5),key(),correlation())).isInstanceOf(DomainFailure.class).hasMessageContaining("four");
  assertThatThrownBy(()->tickets.quote(identity,j.id(),Rail.TravelClass.TWO_AC,Rail.Quota.GENERAL,"NDLS",List.of(new Passenger("Alex","Example",LocalDate.parse("1990-01-01"),Berth.MIDDLE)),key(),correlation())).isInstanceOf(DomainFailure.class).hasMessageContaining("Middle");
  assertThatThrownBy(()->tickets.quote(identity,j.id(),Rail.TravelClass.SL,Rail.Quota.GENERAL,"NDLS",Collections.nCopies(2,people(1).getFirst()),key(),correlation())).isInstanceOf(DomainFailure.class).hasMessageContaining("once");
  assertThat(new Passenger("सोनम","कुमार",LocalDate.parse("1990-01-01"),Berth.NONE).givenName()).isEqualTo("सोनम");
  assertThatThrownBy(()->jdbc.sql("update rail_ticket_quote set payload='{}' where id=:id").param("id",q.quote().id()).update()).isInstanceOf(org.springframework.dao.DataIntegrityViolationException.class);
  tickets.accept(identity,q.quote().id(),1,true,key(),correlation());clock.now=q.quote().expiresAt();assertThatThrownBy(()->tickets.book(identity,q.quote().id(),1,Scenario.SUCCESS,true,key(),correlation())).isInstanceOf(DomainFailure.class).hasMessageContaining("expired");
 }
 @Test void racAndWaitlistAreIssuedWithoutClaimingConfirmedTravelAndPnrIsOwned()throws Exception{
  for(var type:List.of(Rail.TravelClass.SL,Rail.TravelClass.TWO_AC)){var q=quote(type,2);var b=finish(book(q,Scenario.SUCCESS).id());assertThat(b.status()).isEqualTo(Status.ISSUED);assertThat(b.reservation()).isEqualTo(type==Rail.TravelClass.SL?Reservation.RAC:Reservation.WAITLIST);assertThat(b.quote().selection().total().amount()).isEqualByComparingTo(b.quote().selection().availability().total().amount().multiply(java.math.BigDecimal.valueOf(2)));
   var v=tickets.voucher(identity,b.id(),key(),correlation());assertThat(v.content()).contains("NOT VALID FOR TRAVEL",b.reservation().name(),"DOES NOT GUARANTEE").doesNotContain("1990-01-01");assertThat(tickets.readVoucher(identity,b.id()).sha256()).isEqualTo(v.sha256());assertThat(tickets.voucher(identity,b.id(),key(),correlation()).id()).isEqualTo(v.id());
   assertThat(tickets.pnr(identity,b.supplierReference()).id()).isEqualTo(b.id());var foreign=new CustomerIdentity(issuer.url(),"foreign-"+key());assertThatThrownBy(()->tickets.pnr(foreign,b.supplierReference())).isInstanceOf(DomainFailure.class).hasMessageContaining("not found");assertThat(call("GET","/api/v1/rail-ticket-pnr/1234567890",token,null,null).statusCode()).isEqualTo(422);assertThat(call("GET","/api/v1/rail-ticket-pnr/"+b.supplierReference(),issuer.token("other-"+key(),"bookings:read"),null,null).statusCode()).isEqualTo(404);
  }
 }
 @Test void lostCancellationAndDelayedRefundAreIdempotentAndRemoveDocumentAccess()throws Exception{
  var b=finish(book(quote(),Scenario.SUCCESS).id());tickets.voucher(identity,b.id(),key(),correlation());var cq=tickets.cancellationQuote(identity,b.id(),key(),correlation());assertThat(cq.refundAmount().amount()).isEqualByComparingTo(b.quote().selection().availability().base().amount());assertThat(cq.refundAmount().amount().add(cq.retainedAmount().amount())).isEqualByComparingTo(b.quote().selection().total().amount());String cancelKey=key();tickets.cancel(identity,b.id(),cq.id(),true,true,true,cancelKey,correlation());assertThatThrownBy(()->tickets.readVoucher(identity,b.id())).isInstanceOf(DomainFailure.class);due(b.id());worker.tick();due(b.id());worker.tick();assertThat(tickets.get(identity,b.id()).refund()).isEqualTo(Refund.PENDING);due(b.id());worker.tick();assertThat(count("payment_refund","payment_id",b.id())).isEqualTo(1);clock.now=clock.now.plusSeconds(6);refunds.settleNext();var done=finish(b.id());assertThat(done.status()).isEqualTo(Status.CANCELLED);assertThat(done.refund()).isEqualTo(Refund.SUCCEEDED);assertThat(tickets.cancel(identity,b.id(),cq.id(),true,true,true,cancelKey,correlation()).id()).isEqualTo(b.id());assertThat(count("payment_refund_journal","operation_id",b.operation(Step.REFUND))).isEqualTo(2);assertThat(tickets.pnr(identity,b.supplierReference()).reservation()).isEqualTo(Reservation.CANCELLED);assertThat(tickets.timeline(identity,b.id()).stream().map(e->e.eventType())).contains("RailRefundCompleted");assertThat(jdbc.sql("select count(*) from rail_provider_reservation where id=:id and active").param("id",b.id()).query(Integer.class).single()).isZero();
 }
 @Test void stockContentionAcrossSearchesIsAtomicAndCancellationReleasesCapacity()throws Exception{
  var date=LocalDate.now(ZoneId.of("Asia/Kolkata")).plusDays(day.incrementAndGet());var quotes=List.of(quoteAt(date,Rail.TravelClass.SL,6),quoteAt(date,Rail.TravelClass.SL,6),quoteAt(date,Rail.TravelClass.SL,6));assertThat(quotes.stream().map(q->q.quote().selection().journey().id()).distinct().count()).isEqualTo(3);List<RailReservations.Receipt> results;try(var pool=Executors.newFixedThreadPool(3)){var calls=quotes.stream().<Callable<RailReservations.Receipt>>map(q->()->supplier.reserve(UUID.randomUUID(),UUID.randomUUID(),q.quote(),false)).toList();results=pool.invokeAll(calls).stream().map(f->{try{return f.get();}catch(Exception e){throw new RuntimeException(e);}}).toList();}assertThat(results.stream().filter(r->r.accepted()).count()).isEqualTo(2);var winner=results.stream().filter(r->r.accepted()).findFirst().orElseThrow();supplier.cancel(UUID.randomUUID(),winner.reservationId());var next=supplier.reserve(UUID.randomUUID(),UUID.randomUUID(),quotes.getFirst().quote(),false);assertThat(next.accepted()).isTrue();
 }
 @Test void expiryAfterAuthorizationVoidsWithoutReservationOrCapture(){var q=quote();var b=book(q,Scenario.SUCCESS);worker.tick();worker.tick();assertThat(tickets.get(identity,b.id()).payment()).isEqualTo(Payment.AUTHORIZED);clock.now=q.quote().expiresAt();var done=finish(b.id());assertThat(done.payment()).isEqualTo(Payment.VOIDED);assertThat(done.status()).isEqualTo(Status.FAILED);assertThat(count("payment_journal","payment_id",b.id())).isZero();}
 @Test void cancellationQuoteVersionAndDepartureCutoffsAreEnforced(){var b=finish(book(quote(),Scenario.SUCCESS).id());var cq=tickets.cancellationQuote(identity,b.id(),key(),correlation());clock.now=cq.expiresAt();assertThatThrownBy(()->tickets.cancel(identity,b.id(),cq.id(),true,false,false,key(),correlation())).isInstanceOf(DomainFailure.class);clock.now=b.quote().departure();assertThatThrownBy(()->tickets.cancellationQuote(identity,b.id(),key(),correlation())).isInstanceOf(DomainFailure.class);}
 int child(String phase)throws Exception{Path log=temp.resolve(phase+".log");String cp=System.getProperty("surefire.test.class.path",System.getProperty("java.class.path"));var builder=new ProcessBuilder(Path.of(System.getProperty("java.home"),"bin","java").toString(),"-cp",cp,"com.travbook.support.RailTicketProcess",phase).redirectErrorStream(true).redirectOutput(log.toFile());builder.environment().put("DATABASE_URL",postgres.getJdbcUrl());builder.environment().put("DATABASE_USERNAME",postgres.getUsername());builder.environment().put("DATABASE_PASSWORD",postgres.getPassword());var process=builder.start();boolean done=process.waitFor(30,TimeUnit.SECONDS);if(!done)process.destroyForcibly();assertThat(done).isTrue();int code=process.exitValue();if(code!=0&&code!=29)throw new AssertionError(Files.readString(log));return code;}
}
